def get_legal_moves(
    pokemon_state: PokemonState,
) -> List[Move]:
    """
    Return every attack currently usable by the selected Pokémon.

    Saved attack dictionaries use:

    - Move Name
    - damage_numeric
    - energy_cost
    - Effect Explanation
    """

    legal_moves: List[Move] = []

    attacks = pokemon_state.card.get("attacks", [])

    if not isinstance(attacks, list):
        return legal_moves

    for attack in attacks:
        if not isinstance(attack, dict):
            continue

        move_name = attack.get(
            "Move Name",
            "Unknown Move",
        )

        try:
            damage = float(
                attack.get("damage_numeric", 0) or 0
            )
        except (TypeError, ValueError):
            damage = 0.0

        try:
            required_energy = int(
                attack.get("energy_cost", 0) or 0
            )
        except (TypeError, ValueError):
            required_energy = 0

        usable = (
            pokemon_state.attached_energy
            >= required_energy
        )

        if usable:
            legal_moves.append(
                {
                    "name": str(move_name),
                    "damage": damage,
                    "energy_cost": required_energy,
                    "effect": attack.get(
                        "Effect Explanation"
                    ),
                }
            )

    return legal_moves
